def run_git(args: list[str], input_bytes: bytes | None = None) -> str:
    """Execute git with pipe stdio and utf-8 decoding."""
    result = subprocess.run(
        ["git", *args],
        input=input_bytes,
        capture_output=True,
        check=True,
    )
    return result.stdout.decode("utf-8", errors="replace")

def blob_bytes(spec: str) -> int | None:
    """Return byte size of a git blob spec (e.g. ':path' or 'HEAD:path')."""
    try:
        out = run_git(["cat-file", "-s", spec]).strip()
        return int(out)
    except (subprocess.CalledProcessError, OSError, ValueError):
        return None

def get_git_root() -> Path:
    """Return git repo toplevel directory."""
    out = run_git(["rev-parse", "--show-toplevel"]).strip()
    return Path(out).resolve()

def linearize(channel: int) -> float:
    c = channel / 255.0
    if c <= 0.03928:
        return c / 12.92
    return ((c + 0.055) / 1.055) ** 2.4

def luminance(rgb: tuple[int, int, int]) -> float:
    r, g, b = (linearize(ch) for ch in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast_ratio(
    color_a: tuple[int, int, int], color_b: tuple[int, int, int]
) -> float:
    lum_a, lum_b = luminance(color_a), luminance(color_b)
    lighter, darker = max(lum_a, lum_b), min(lum_a, lum_b)
    return (lighter + 0.05) / (darker + 0.05)

def parse_hex(value: str) -> tuple[int, int, int]:
    clean = value.strip().lstrip("#")
    if len(clean) == 3:
        clean = "".join(ch * 2 for ch in clean)
    if not re.fullmatch(r"[0-9A-Fa-f]{6}", clean):
        raise ValueError(f"expected a hex color like #FFFFFF, got {value!r}")
    return (int(clean[0:2], 16), int(clean[2:4], 16), int(clean[4:6], 16))

def parse_color(value: str) -> tuple[int, int, int]:
    val = value.strip().lower()
    if val in NAMED_COLORS:
        return NAMED_COLORS[val]
    return parse_hex(value)

def parse_pairing(pairing: str) -> tuple[tuple[int, int, int], tuple[int, int, int]]:
    """Turn 'White on #333333' or '#555555 on black' into two RGB tuples."""
    colors = []
    for token in re.split(r"\s+on\s+", pairing):
        token = token.strip()
        match = re.search(r"#[0-9A-Fa-f]{3,6}", token)
        if match:
            colors.append(parse_hex(match.group(0)))
        elif token.lower() in NAMED_COLORS:
            colors.append(NAMED_COLORS[token.lower()])
        else:
            raise ValueError(f"cannot parse {token!r} from pairing {pairing!r}")
    if len(colors) != 2:
        raise ValueError(f"expected two colors in pairing {pairing!r}")
    return (colors[0], colors[1])

def parse_reference_rows(text: str) -> list[dict[str, str | float]]:
    rows: list[dict[str, str | float]] = []
    in_table = False
    for raw in text.splitlines():
        line = raw.strip()
        if line.startswith(REFERENCE_HEADER):
            in_table = True
            continue
        if not in_table:
            continue
        if not line.startswith("|"):
            break
        if line.startswith("|---"):
            continue
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if len(cells) != 4:
            continue
        pairing, ratio_str, normal, large = cells
        rows.append(
            {
                "pairing": pairing,
                "ratio": float(ratio_str),
                "normal": normal,
                "large": large,
            }
        )
    return rows

def selftest() -> tuple[int, str]:
    text = _get_skill_doc_text()
    if text is None:
        return (
            2,
            "selftest: antislop-human/SKILL.md reference doc not found; cannot check table",
        )

    try:
        rows = parse_reference_rows(text)
    except Exception as exc:  # noqa: BLE001
        return 1, f"selftest: could not read table from SKILL.md: {exc}"

    if not rows:
        return 1, "selftest: no reference rows found in SKILL.md"

    failures = []
    for row in rows:
        pairing_str = str(row["pairing"])
        color_a, color_b = parse_pairing(pairing_str)
        raw = contrast_ratio(color_a, color_b)
        computed = round(raw, 2)
        expected_normal = "Pass" if raw >= 4.5 else "Fail"
        expected_large = "Pass" if raw >= 3.0 else "Fail"

        if f"{computed:.2f}" != f"{float(row['ratio']):.2f}":
            failures.append(
                f"selftest: {pairing_str}: table says {row['ratio']}, formula says {computed:.2f}"
            )
        if row["normal"] != expected_normal:
            failures.append(
                f"selftest: {pairing_str}: normal text marked {row['normal']}, should be {expected_normal}"
            )
        if row["large"] != expected_large:
            failures.append(
                f"selftest: {pairing_str}: large text marked {row['large']}, should be {expected_large}"
            )

    if failures:
        return 1, "\n".join(failures)
    return 0, f"selftest: {len(rows)} reference pairs OK"

def looks_like_argument(token: str) -> bool:
    if token.startswith("-"):
        return True
    if "/" in token or "\\" in token:
        return True
    if re.search(r"\.\w{1,6}$", token):
        return True
    if "=" in token:
        return True
    if token.startswith(("'", '"')) or "%[" in token or "{" in token:
        return True
    if re.match(r"^\w+:$", token):
        return True
    return bool(token.startswith(("$", "@", "#")))

def is_invocation(line: str) -> bool:
    stripped = re.sub(r"^\s*[$>]\s+", "", line).strip()
    if not stripped:
        return False
    tokens = stripped.split()
    head = os.path.basename(tokens[0])
    runnable = (
        head in TOOLS
        or tokens[0].startswith(("./", "../", "/"))
        or bool(re.match(r"^\w[\w.-]*\.(?:mjs|js|py|sh)$", head))
    )
    if not runnable:
        return False
    return any(looks_like_argument(t) for t in tokens[1:])

def parse_receipt_lines(lines: list[str]) -> list[bool]:
    """Flag which lines belong to a fenced block, indented code, or shell transcript."""
    in_receipt = [False] * len(lines)
    fence: str | None = None
    transcript = False

    for i, line in enumerate(lines):
        fence_match = re.match(r"^\s*(`{3,}|~{3,})", line)
        if fence_match:
            if fence is None:
                fence = fence_match.group(1)[:3]
                in_receipt[i] = True
                continue
            if fence_match.group(1).startswith(fence):
                fence = None
                in_receipt[i] = True
                continue
        if fence is not None:
            in_receipt[i] = True
            continue

        if re.match(r"^\s{4,}\S", line) and not re.match(r"^\s*[-*+]\s", line):
            in_receipt[i] = True
            continue

        if re.match(r"^\s*\$\s+\S", line):
            in_receipt[i] = True
            transcript = True
            continue
        if transcript:
            if not line.strip():
                transcript = False
            else:
                in_receipt[i] = True

    return in_receipt

def extract_receipt_runs(lines: list[str]) -> list[ReceiptRun]:
    """Group contiguous receipt lines into runs and collect command and outputs."""
    in_receipt = parse_receipt_lines(lines)
    runs: list[ReceiptRun] = []
    i = 0
    n = len(lines)

    while i < n:
        if not in_receipt[i]:
            i += 1
            continue
        start = i
        while i < n and in_receipt[i]:
            i += 1
        end = i

        block_lines = lines[start:end]
        inv_idx = -1
        for idx, bline in enumerate(block_lines):
            if is_invocation(bline):
                inv_idx = idx
                break

        if inv_idx != -1 and inv_idx + 1 < len(block_lines):
            cmd = block_lines[inv_idx].strip()
            out_lines = [l for l in block_lines[inv_idx + 1 :] if not is_invocation(l)]
            if out_lines:
                run = ReceiptRun(
                    start_line=start, end_line=end, command=cmd, output_lines=out_lines
                )
                for ol in out_lines:
                    for m in NUMBER_RE.finditer(ol):
                        run.numbers.add(m.group(1))
                    for m in HEX_RE.finditer(ol):
                        run.hexes.add(m.group(1).lower())
                runs.append(run)

    return runs

