def make_node_id(kind: str, qualified_name: str, start_line: int) -> str:
        base_id = symbol_node_id(kind, rel_path, qualified_name)
        prior = used_ids.get(base_id)
        if prior is None:
            used_ids[base_id] = (rel_path, start_line)
            return base_id
        if prior == (rel_path, start_line):
            return base_id
        return f"{base_id}:L{start_line}"

def add_node(self, node: GraphNode) -> GraphNode:
        existing = self.nodes.get(node.id)
        if existing is not None:
            return existing
        self.nodes[node.id] = node
        return node

def get_or_create_external(self, dotted_name: str) -> GraphNode:
        node_id = external_node_id(dotted_name)
        existing = self.nodes.get(node_id)
        if existing is not None:
            return existing
        node = GraphNode(
            id=node_id,
            kind=EXTERNAL,
            name=dotted_name.rsplit(".", 1)[-1],
            qualified_name=dotted_name,
            external=True,
        )
        return self.add_node(node)

