def walk(node: ts.Node) -> None:
        # If this is a block node belonging to a function/method/callable, prune it
        parent = node.parent
        parent_type = parent.type if parent else None

        if is_block_node(node.type):
            if is_callable_parent(parent_type):
                blocks_to_replace.append((node.start_byte, node.end_byte))
                return
            # If parent is a class, we want to walk its children to prune methods inside
            if parent_type and "class" in parent_type.lower():
                for child in node.children:
                    walk(child)
                return
            # For general top-level or control flow blocks inside functions
            blocks_to_replace.append((node.start_byte, node.end_byte))
            return

        for child in node.children:
            walk(child)

def prune_signatures(filepath: str, code: bytes) -> str:
    """Returns the code with internal block logic replaced by placeholders."""
    path = Path(filepath)
    ext = path.suffix.lower()
    lang_id = EXTENSION_TO_LANGUAGE.get(ext)
    if not lang_id:
        return code.decode("utf-8", errors="replace")

    spec = get_spec(lang_id)
    if not spec:
        return code.decode("utf-8", errors="replace")

    parser = ts.Parser(spec.language)
    tree = parser.parse(code)

    if tree.root_node.has_error:
        logging.warning("Syntax error detected in %s, falling back to raw code.", filepath)
        return code.decode("utf-8", errors="replace")

    blocks_to_replace: list[tuple[int, int]] = []

    def walk(node: ts.Node) -> None:
        # If this is a block node belonging to a function/method/callable, prune it
        parent = node.parent
        parent_type = parent.type if parent else None

        if is_block_node(node.type):
            if is_callable_parent(parent_type):
                blocks_to_replace.append((node.start_byte, node.end_byte))
                return
            # If parent is a class, we want to walk its children to prune methods inside
            if parent_type and "class" in parent_type.lower():
                for child in node.children:
                    walk(child)
                return
            # For general top-level or control flow blocks inside functions
            blocks_to_replace.append((node.start_byte, node.end_byte))
            return

        for child in node.children:
            walk(child)

    walk(tree.root_node)

    # Sort blocks by start byte descending to replace without shifting earlier offsets
    blocks_to_replace.sort(key=lambda x: x[0], reverse=True)

    placeholder = get_placeholder(ext)
    mutated_code = bytearray(code)

    for start, end in blocks_to_replace:
        if ext == ".py":
            replacement = b"\n    " + placeholder + b"\n"
        else:
            replacement = b" { " + placeholder + b" }"

        mutated_code[start:end] = replacement

    return mutated_code.decode("utf-8", errors="replace")

def extract_map(filepath: str, code: bytes) -> str:
    """Extracts module linkages (imports) and API surface boundaries (exports, top-level classes)."""
    path = Path(filepath)
    ext = path.suffix.lower()
    lang_id = EXTENSION_TO_LANGUAGE.get(ext)
    if not lang_id:
        return code.decode("utf-8", errors="replace")

    spec = get_spec(lang_id)
    if not spec:
        return code.decode("utf-8", errors="replace")

    parser = ts.Parser(spec.language)
    tree = parser.parse(code)

    if tree.root_node.has_error:
        logging.warning("Syntax error detected in %s, falling back to raw code.", filepath)
        return code.decode("utf-8", errors="replace")

    output_parts: list[str] = []

    for node in tree.root_node.children:
        nt = node.type.lower()
        if "import" in nt or "require" in nt:
            output_parts.append(code[node.start_byte:node.end_byte].decode("utf-8", errors="replace"))
        elif "class" in nt or "export" in nt or "interface" in nt or "function" in nt:
            node_code = code[node.start_byte:node.end_byte]
            pruned_node = prune_signatures(filepath, node_code)
            output_parts.append(pruned_node)

    return "\n\n".join(output_parts)

class FileViolation:
    path: str
    bytes: int
    before: int | None

    @property
    def tokens(self) -> int:
        return round(self.bytes / 4)

    @property
    def before_tokens(self) -> int | None:
        return round(self.before / 4) if self.before is not None else None

def check_staged_files(
    paths: list[str], max_tokens: int = 8000
) -> tuple[int, list[str]]:
    """Verify staged versions of paths against ratchet."""
    max_bytes = max_tokens * 4
    try:
        root = get_git_root()
    except (subprocess.CalledProcessError, OSError) as exc:
        return 2, [f"error: not a git repository: {exc}"]

    # Get renames from index
    renames: dict[str, str] = {}
    try:
        diff_out = run_git(["diff", "--cached", "--find-renames", "--name-status"])
        for line in diff_out.splitlines():
            parts = line.split("\t")
            if len(parts) >= 3 and parts[0].startswith("R"):
                renames[parts[2]] = parts[1]
    except (subprocess.CalledProcessError, OSError):
        pass

    normalized: list[str] = []
    for p in paths:
        try:
            rel = os.path.relpath(os.path.realpath(p), root)
        except (ValueError, OSError):
            rel = os.path.relpath(p, root)
        rel_posix = rel.replace("\\", "/")
        if is_source_file(rel_posix):
            normalized.append(rel_posix)

    unauthored = get_unauthored(normalized)
    eval_paths = [p for p in normalized if p not in unauthored]

    failures: list[FileViolation] = []
    for p in eval_paths:
        size = blob_bytes(f":{p}")
        if size is None or size <= max_bytes or is_ignored(f":{p}"):
            continue
        orig = renames.get(p, p)
        before = blob_bytes(f"HEAD:{orig}")
        if before is not None and size <= before:
            continue
        failures.append(FileViolation(path=p, bytes=size, before=before))

    if not failures:
        return 0, []

    lines = [
        f"Commit refused: source files over the budget of {format_tokens(max_bytes)} (bytes // 4)."
    ]
    for f in failures:
        frozen = f.before is not None and f.before > max_bytes
        limit: int = f.before if (frozen and f.before is not None) else max_bytes
        if frozen and f.before is not None:
            why = (
                f"already over budget at {format_tokens(f.before)}, so it may not grow"
            )
        elif f.before is None:
            why = "a new file, so it must fit the budget"
        else:
            why = f"was {format_tokens(f.before)}, so it must fit the budget"
        lines.append(f"  {f.path}: {format_tokens(f.bytes)}, {why}.")
        lines.append(f"    Cut at least {f.bytes - limit:,} bytes.")

    return 1, lines

